          "id": "villakey-emerald-island-8534-procedure-001",
          "sourceNumber": 1,
          "name": "Check-in, Check-out & Arrival/Departure",
          "isGeneralProcedure": false,
          "category": "chat-prearrival",
          "sourceCategory": "Check-in, Check-out & Arrival/Departure",
